CREATE COLUMN TABLE "TEST_AP"."RTM2" ("LineNum" INTEGER CS_INT NOT NULL , "IsSysCurr" NVARCHAR(1) DEFAULT 'N' NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "AcctCode" NVARCHAR(15) NOT NULL , "TransAmtSC" DECIMAL(21,6) CS_FIXED, "BalDueSC" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("LineNum", "IsSysCurr", "CardCode", "AcctCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "RTM2_CARD_CODE" ON "TEST_AP"."RTM2" ( "CardCode" ASC )